// 應用程式全域狀態
const state = {
  currentUser: null,
  activeTab: 'dashboard',
  dashboardSubTab: 'fitness', // 'fitness' | 'fees' | 'leaves' | 'equipment'
  scheduleSubTab: 'calendar', // 'calendar' (臨時更改行程) | 'batch' (固定練球計畫) | 'academic' (每年輸入開學與放假日期)
  fitnessSubTab: 'matrix',    // 'matrix' (體能紀錄 / 三組動作組數表) | 'makeup' (補體能專區)
  feesSubTab: 'overview',     // 'overview' (依項目/球員彙整) | 'all' (全部細項) | 'team' (隊費) | 'proxy' (代繳費用)
  leavesSubTab: 'calendar',   // 'calendar' (球隊行事曆＋當日出席) | 'leave' (請假登記與明細) | 'makeupStats' (需補體能次數) | 'equipment' (借還器材日曆)
  financesSubTab: 'overview', // 'overview' (科目分類收支彙整) | 'list' (收支細項流水帳)
  settingsSubTab: 'personal', // 'personal' (個人帳號與密碼) | 'members' (全隊成員帳號管理)
  adminViewMode: 'summary', // 'summary' (粗略項目彙整) 或 'detail' (細項明細逐筆)
  selectedAcademicYear: '', // 例如 '114'、'115'、'116' 或 'all'
  selectedTermPeriod: '',   // '暑假' | '上學期' | '寒假' | '下學期' | 'all'
  selectedFitnessPlayer: '',
  selectedFitnessDate: '',
  selectedAttendanceDate: '',
  selectedLeavePlayer: '',
  selectedLeaveDate: '', scheduleCalendarMonth: '', equipmentCalendarMonth: '', selectedEquipDate: '',
  adminAssignEquipMember: '',
  adminAssignEquipRole: '借器材',
  equipSectionsExpanded: { reminder: false, list: false, rules: false },
  isSupabaseReady: false,
  users: [],
  fitness: [],
  fees: [],
  leaves: [],
  finances: [],
  realtimeChannel: null,
  pollTimer: null,
  editingBatchRuleId: null,
  batchScheduleDraft: {
    isDirty: false,
    startDate: '',
    endDate: '',
    weekdays: null,
    type: '',
    practiceTime: '',
    startTime: '',
    endTime: '',
    planNote: ''
  }
};

// ============================================================================
// 學年度（如 114、115）與期間（暑假、上學期、寒假、下學期）日曆區間引擎
// 規則：
// - 學年度起訖：每年 8/1 起 ～ 隔年 7/31 止（例如 115 學年度 = 2026-08-01 ~ 2027-07-31；2026年7月屬 114 學年度）
// - 四大期間劃分（以學年度起算西元年 startYear = 學年度 + 1911，隔年 endYear = 學年度 + 1912）：
//   1. 暑假：startYear-08-01 ~ startYear-09-06（8月起新學年～9/7開學前）及 endYear-06-28 ~ endYear-07-31（6/28暑假開始～7/31學年底）
//   2. 上學期：startYear-09-07（9/7開學）~ endYear-01-10（1/11放寒假前）
//   3. 寒假：endYear-01-11（1/11開始放寒假）~ endYear-02-21（2/22下學期開學前）
//   4. 下學期：endYear-02-22（2/22下學期開學）~ endYear-06-27（6/28暑假開始前）
// ============================================================================
const ACADEMIC_PERIOD_DEFS = [
  { id: '暑假', label: '暑假', icon: '☀️', shortDesc: '8/1~開學前 及 暑假起~7/31' },
  { id: '上學期', label: '上學期', icon: '🎒', shortDesc: '開學 ~ 寒假前' },
  { id: '寒假', label: '寒假', icon: '❄️', shortDesc: '放寒假 ~ 下學期開學前' },
  { id: '下學期', label: '下學期', icon: '🌱', shortDesc: '下學期開學 ~ 暑假前' }
];

function addDaysToDateStr(dateStr, deltaDays) {
  if (!dateStr || dateStr.length < 10) return dateStr;
  const [y, m, d] = dateStr.slice(0, 10).split('-').map(Number);
  if (!y || !m || !d) return dateStr;
  const dt = new Date(Date.UTC(y, m - 1, d + deltaDays));
  const ry = dt.getUTCFullYear();
  const rm = String(dt.getUTCMonth() + 1).padStart(2, '0');
  const rd = String(dt.getUTCDate()).padStart(2, '0');
  return `${ry}-${rm}-${rd}`;
}

function isSystemScheduleRecord(r) {
  return r && r.session_name === '__SYS_SCHEDULE__';
}
function isSystemEquipRecord(r) {
  return r && r.session_name === '__SYS_EQUIP__';
}
function isSystemAcademicConfigRecord(r) {
  return r && r.session_name === '__SYS_ACADEMIC_CALENDAR__';
}
function isSystemSpecialEventRecord(r) {
  return r && r.session_name === '__SYS_SPECIAL_EVENT__';
}
function isSystemEquipConfigRecord(r) {
  return r && r.session_name === '__SYS_EQUIP_CONFIG__';
}
function isNormalLeaveRecord(r) {
  return r &&
    r.session_name !== '__SYS_SCHEDULE__' &&
    r.session_name !== '__SYS_EQUIP__' &&
    r.session_name !== '__SYS_ACADEMIC_CALENDAR__' &&
    r.session_name !== '__SYS_SPECIAL_EVENT__' &&
    r.session_name !== '__SYS_EQUIP_CONFIG__';
}
function getRealLeaves() {
  return state.leaves.filter(isNormalLeaveRecord);
}
function getScheduleRecords() {
  return state.leaves.filter(isSystemScheduleRecord);
}
function isHistoricalSeedEquipRecord(r) {
  return r && (
    (r.id && String(r.id).startsWith('e0000000-0000-4000-8000-')) ||
    (r.reason && String(r.reason).includes('累計紀錄算1次'))
  );
}
function getEquipmentRecords() {
  return state.leaves.filter(r => isSystemEquipRecord(r) && !isHistoricalSeedEquipRecord(r));
}
function getAcademicConfigRecords() {
  return state.leaves.filter(isSystemAcademicConfigRecord);
}
function getSpecialEventRecords() {
  return state.leaves.filter(isSystemSpecialEventRecord);
}
function getEquipmentConfigRecord() {
  return state.leaves.find(isSystemEquipConfigRecord);
}

// 取得指定學年度＋期間（例如 115 學年度・上學期）的「長時間固定練球計畫」設定（於區塊一儲存）
function getTermLongTermPlanConfig(academicYear, period) {
  const ay = academicYear === 'all' ? (getAcademicTermInfo(getTodayStr()).academicYear || 115) : (Number(academicYear) || 115);
  const per = (!period || period === 'all') ? (getAcademicTermInfo(getTodayStr()).period || '上學期') : period;
  const planKey = `PLAN_${ay}_${per}`;
  const sysRec = getAcademicConfigRecords().find(r => r.leave_type === planKey);
  if (sysRec && sysRec.reason) {
    try {
      const parsed = JSON.parse(sysRec.reason);
      const rawRules = Array.isArray(parsed.rules) ? parsed.rules : [];
      return {
        academicYear: ay,
        period: per,
        planNote: parsed.planNote || '',
        rules: rawRules.map((r, idx) => ({
          id: r.id || `rule_${ay}_${per}_${idx}_${(r.weekdays || []).join('')}`,
          ...r
        })),
        updatedAt: parsed.updatedAt || ''
      };
    } catch (e) {
      // ignore
    }
  }
  return {
    academicYear: ay,
    period: per,
    planNote: '',
    rules: [],
    updatedAt: ''
  };
}

// 取得指定學年度（如 114, 115, 116）的開學與放假日期設定（支援管理者於「行事曆與練球排程」自訂並雲端同步）
function getAcademicYearDatesConfig(academicYear) {
  const ay = Number(academicYear) || 115;
  const startYear = ay + 1911;
  const endYear = ay + 1912;

  const defaults = {
    academicYear: ay,
    yearStart: `${startYear}-08-01`,
    sem1Start: `${startYear}-09-07`,
    winterStart: `${endYear}-01-11`,
    sem2Start: `${endYear}-02-22`,
    summerStart: `${endYear}-06-28`,
    yearEnd: `${endYear}-07-31`,
    defaultPracticeTime: '18:30~21:30'
  };

  let custom = null;
  const sysRec = getAcademicConfigRecords().find(r => String(r.leave_type) === String(ay));
  if (sysRec && sysRec.reason) {
    try {
      custom = JSON.parse(sysRec.reason);
    } catch (e) {
      custom = null;
    }
  }

  const merged = {
    ...defaults,
    ...(custom || {}),
    academicYear: ay
  };

  merged.summer1End = addDaysToDateStr(merged.sem1Start, -1);
  merged.sem1End = addDaysToDateStr(merged.winterStart, -1);
  merged.winterEnd = addDaysToDateStr(merged.sem2Start, -1);
  merged.sem2End = addDaysToDateStr(merged.summerStart, -1);
  merged.isCustomized = Boolean(custom);

  return merged;
}

function getAcademicTermInfo(dateStr) {
  const d = (dateStr || getTodayStr()).slice(0, 10);
  const parts = d.split('-');
  if (parts.length < 3) {
    return { academicYear: 115, period: '上學期', periodKey: '上學期', subSegment: 'sem1', label: '115學年度・上學期' };
  }
  const yyyy = Number(parts[0]);
  const mmdd = `${parts[1]}-${parts[2]}`;

  // 先檢查是否有管理者自訂學年度起訖涵蓋此日期，否則預設 8/1 起歸屬新學年度、7/31 前歸屬上一學年度
  let academicYear = mmdd >= '08-01' ? (yyyy - 1911) : (yyyy - 1912);
  const customRecs = getAcademicConfigRecords();
  for (const r of customRecs) {
    const candidateAy = Number(r.leave_type);
    if (candidateAy) {
      const cfg = getAcademicYearDatesConfig(candidateAy);
      if (d >= cfg.yearStart && d <= cfg.yearEnd) {
        academicYear = candidateAy;
        break;
      }
    }
  }

  const dates = getAcademicYearDatesConfig(academicYear);
  let period = '上學期';
  let subSegment = 'sem1';

  if (d >= dates.yearStart && d < dates.sem1Start) {
    period = '暑假';
    subSegment = 'aug_sep'; // 學年初暑假 (8/1 ~ 開學前一日)
  } else if (d >= dates.sem1Start && d < dates.winterStart) {
    period = '上學期';
    subSegment = 'sem1'; // 上學期 (開學日 ~ 寒假前一日)
  } else if (d >= dates.winterStart && d < dates.sem2Start) {
    period = '寒假';
    subSegment = 'winter'; // 寒假 (寒假開始日 ~ 下學期開學前一日)
  } else if (d >= dates.sem2Start && d < dates.summerStart) {
    period = '下學期';
    subSegment = 'sem2'; // 下學期 (下學期開學日 ~ 暑假開始前一日)
  } else {
    period = '暑假';
    subSegment = 'jun_jul'; // 學年末暑假 (暑假開始日 ~ 7/31)
  }

  return {
    academicYear,
    period,
    periodKey: period,
    subSegment,
    label: `${academicYear}學年度・${period}`
  };
}

function ensureAcademicPeriodInitialized() {
  const todayInfo = getAcademicTermInfo(getTodayStr());
  if (!state.selectedAcademicYear) {
    state.selectedAcademicYear = String(todayInfo.academicYear);
  }
  if (!state.selectedTermPeriod) {
    state.selectedTermPeriod = todayInfo.period;
  }
}

function getAvailableAcademicYears() {
  const yearSet = new Set([114, 115, 116]);
  const todayInfo = getAcademicTermInfo(getTodayStr());
  if (todayInfo.academicYear) yearSet.add(todayInfo.academicYear);
  getAcademicConfigRecords().forEach(r => {
    const ay = Number(r.leave_type);
    if (ay) yearSet.add(ay);
  });
  state.fitness.forEach(f => {
    if (f.target_date) yearSet.add(getAcademicTermInfo(f.target_date).academicYear);
  });
  state.leaves.forEach(l => {
    if (l.leave_date && !isSystemAcademicConfigRecord(l)) {
      yearSet.add(getAcademicTermInfo(l.leave_date).academicYear);
    }
  });
  return Array.from(yearSet).filter(Boolean).sort((a, b) => b - a);
}

function getMonthsBetweenDates(startDateStr, endDateStr, noteText, defaultDateOverride = '') {
  if (!startDateStr || !endDateStr || startDateStr > endDateStr) return [];
  const res = [];
  let [cy, cm] = startDateStr.slice(0, 7).split('-').map(Number);
  const [ey, em] = endDateStr.slice(0, 7).split('-').map(Number);
  let safety = 0;
  while ((cy < ey || (cy === ey && cm <= em)) && safety < 24) {
    safety++;
    const ym = `${cy}-${String(cm).padStart(2, '0')}`;
    const isFirst = ym === startDateStr.slice(0, 7);
    const isLast = ym === endDateStr.slice(0, 7);
    let labelSuffix = '';
    if (isFirst && startDateStr.slice(8, 10) !== '01') {
      labelSuffix = ` (${Number(startDateStr.slice(5, 7))}/${Number(startDateStr.slice(8, 10))}~)`;
    } else if (isLast && endDateStr.slice(8, 10) < '28') {
      labelSuffix = ` (~${Number(endDateStr.slice(5, 7))}/${Number(endDateStr.slice(8, 10))})`;
    }
    res.push({
      ym,
      shortLabel: `${cy}年${cm}月${labelSuffix}`,
      note: noteText,
      defaultDate: isFirst ? (defaultDateOverride || startDateStr) : `${ym}-01`
    });
    cm++;
    if (cm > 12) {
      cm = 1;
      cy++;
    }
  }
  return res;
}

function getAcademicPeriodConfig(academicYear, period) {
  ensureAcademicPeriodInitialized();
  const ayRaw = academicYear || state.selectedAcademicYear || '115';
  const per = period || state.selectedTermPeriod || '上學期';
  const todayAy = getAcademicTermInfo(getTodayStr()).academicYear || 115;
  const ay = ayRaw === 'all' ? todayAy : Number(ayRaw);
  const startYear = ay + 1911;
  const endYear = ay + 1912;
  const dates = getAcademicYearDatesConfig(ay);
  const fmtSlash = (ds) => (ds || '').replace(/-/g, '/');
  const aySpanText = `${fmtSlash(dates.yearStart)} ～ ${fmtSlash(dates.yearEnd)}`;

  let rangeText = '';
  let detailNote = '';
  let months = [];
  let ranges = [];

  if (per === '暑假') {
    rangeText = `${fmtSlash(dates.yearStart)}～${fmtSlash(dates.summer1End)}、${fmtSlash(dates.summerStart)}～${fmtSlash(dates.yearEnd)}`;
    detailNote = ay === 114
      ? `114學年度暑假：含 ${fmtSlash(dates.summerStart)}～${fmtSlash(dates.yearEnd)}（7月屬 114 學年度，8月起屬 115 學年度）及 ${fmtSlash(dates.yearStart)}～${fmtSlash(dates.summer1End)}`
      : `${ay}學年度暑假：${fmtSlash(dates.yearStart)}～${fmtSlash(dates.summer1End)}（${fmtSlash(dates.sem1Start)} 開學前）及 ${fmtSlash(dates.summerStart)}～${fmtSlash(dates.yearEnd)}`;
    const mPart1 = getMonthsBetweenDates(dates.yearStart, dates.summer1End, '學年初暑假');
    const mPart2 = getMonthsBetweenDates(dates.summerStart, dates.yearEnd, '學年末暑假');
    const seenYm = new Set();
    months = [...mPart1, ...mPart2].filter(m => {
      if (seenYm.has(m.ym)) return false;
      seenYm.add(m.ym);
      return true;
    });
    ranges = [
      { start: dates.yearStart, end: dates.summer1End },
      { start: dates.summerStart, end: dates.yearEnd }
    ];
  } else if (per === '上學期') {
    rangeText = `${fmtSlash(dates.sem1Start)} ～ ${fmtSlash(dates.sem1End)}`;
    detailNote = `${ay}學年度上學期：${fmtSlash(dates.sem1Start)} 開學 ～ ${fmtSlash(dates.sem1End)}（${fmtSlash(dates.winterStart)} 開始放寒假）`;
    months = getMonthsBetweenDates(dates.sem1Start, dates.sem1End, '上學期');
    ranges = [{ start: dates.sem1Start, end: dates.sem1End }];
  } else if (per === '寒假') {
    rangeText = `${fmtSlash(dates.winterStart)} ～ ${fmtSlash(dates.winterEnd)}`;
    detailNote = `${ay}學年度寒假：${fmtSlash(dates.winterStart)} 開始放寒假 ～ ${fmtSlash(dates.winterEnd)}（${fmtSlash(dates.sem2Start)} 下學期開學前）`;
    months = getMonthsBetweenDates(dates.winterStart, dates.winterEnd, '寒假');
    ranges = [{ start: dates.winterStart, end: dates.winterEnd }];
  } else if (per === '下學期') {
    rangeText = `${fmtSlash(dates.sem2Start)} ～ ${fmtSlash(dates.sem2End)}`;
    detailNote = `${ay}學年度下學期：${fmtSlash(dates.sem2Start)} 下學期開學 ～ ${fmtSlash(dates.sem2End)}（${fmtSlash(dates.summerStart)} 暑假開始前）`;
    months = getMonthsBetweenDates(dates.sem2Start, dates.sem2End, '下學期');
    ranges = [{ start: dates.sem2Start, end: dates.sem2End }];
  } else {
    // 'all' 整學年
    rangeText = `${fmtSlash(dates.yearStart)} ～ ${fmtSlash(dates.yearEnd)}（全學年）`;
    detailNote = `${ayRaw === 'all' ? '全部學年度' : `${ay}學年度`}：${fmtSlash(dates.yearStart)} ～ ${fmtSlash(dates.yearEnd)}（含暑假、上學期、寒假、下學期）`;
    months = getMonthsBetweenDates(dates.yearStart, dates.yearEnd, '全學年');
    ranges = [{ start: dates.yearStart, end: dates.yearEnd }];
  }

  const titleLabel = `${ayRaw === 'all' ? '全部學年度' : `${ay}學年度`}・${per === 'all' ? '全學年期間' : per}`;
  return {
    academicYear: ayRaw === 'all' ? 'all' : ay,
    numericYear: ay,
    period: per,
    startYear,
    endYear,
    dates,
    aySpanText,
    rangeText,
    detailNote,
    months,
    ranges,
    titleLabel,
    fullTitle: titleLabel
  };
}

function isDateInAcademicPeriod(dateStr, academicYear = state.selectedAcademicYear, period = state.selectedTermPeriod) {
  if (!dateStr) return false;
  ensureAcademicPeriodInitialized();
  const ayFilter = academicYear || state.selectedAcademicYear || 'all';
  const perFilter = period || state.selectedTermPeriod || 'all';
  const info = getAcademicTermInfo(dateStr);
  if (ayFilter !== 'all' && String(info.academicYear) !== String(ayFilter)) {
    return false;
  }
  if (perFilter !== 'all' && info.period !== perFilter) {
    return false;
  }
  return true;
}

// ----------------------------------------------------------------------------
// 特殊行程與盃賽管理 (迎新聚餐、大專盃、媽祖盃等，主頁倒數計時)
// ----------------------------------------------------------------------------
function getSpecialEvents() {
  const recs = getSpecialEventRecords();
  const parsed = recs.map(r => {
    let meta = {};
    try {
      meta = JSON.parse(r.reason || '{}');
    } catch (e) {
      meta = { title: r.reason || '特殊行程' };
    }
    return {
      id: r.id,
      title: meta.title || r.reason || '特殊行程',
      date: r.leave_date,
      category: r.leave_type || meta.category || '活動',
      location: meta.location || '',
      note: meta.note || '',
      isCup: (r.leave_type === '盃賽') || meta.isCup || (meta.title || '').includes('盃') || (meta.title || '').includes('聯賽') || (meta.title || '').includes('錦標賽')
    };
  });

  // 若資料庫尚未登記任何特殊行程，提供預設盃賽與特殊行程範例，讓使用者立即見效
  if (parsed.length === 0) {
    return [
      { id: 'cup-demo-1', title: '大專盃排球聯賽 (預賽)', date: '2026-11-22', category: '盃賽', location: '中興大學體育館', note: '全員備戰，大專盃倒數', isCup: true, isDemo: true },
      { id: 'cup-demo-2', title: '北港媽祖盃排球錦標賽', date: '2026-12-13', category: '盃賽', location: '雲林北港高中', note: '年度重大盃賽', isCup: true, isDemo: true },
      { id: 'event-demo-3', title: '排球隊迎新聚餐', date: '2026-10-31', category: '聚餐', location: '逢甲周邊餐廳', note: '全員出席迎新隊聚', isCup: false, isDemo: true }
    ];
  }
  return parsed.sort((a, b) => (a.date || '').localeCompare(b.date || ''));
}

function openSpecialEventModal(eventId = null) {
  const form = document.getElementById('form-special-event');
  if (form) form.reset();
  document.getElementById('special-event-id').value = '';
  document.getElementById('special-event-date').value = getTodayStr();

  const titleEl = document.getElementById('special-event-modal-title');
  if (titleEl) titleEl.textContent = '新增特殊行程 / 盃賽';

  if (eventId) {
    const ev = getSpecialEvents().find(e => e.id === eventId);
    if (ev) {
      document.getElementById('special-event-id').value = ev.id;
      document.getElementById('special-event-title').value = ev.title;
      document.getElementById('special-event-category').value = ev.category;
      document.getElementById('special-event-date').value = ev.date;
      document.getElementById('special-event-location').value = ev.location || '';
      document.getElementById('special-event-note').value = ev.note || '';
      if (titleEl) titleEl.textContent = '編輯特殊行程 / 盃賽';
    }
  }
  document.getElementById('modal-special-event').classList.remove('hidden');
}

async function submitSpecialEventForm(e) {
  e.preventDefault();
  const id = document.getElementById('special-event-id').value.trim();
  const title = document.getElementById('special-event-title').value.trim();
  const category = document.getElementById('special-event-category').value;
  const date = document.getElementById('special-event-date').value;
  const location = document.getElementById('special-event-location').value.trim();
  const note = document.getElementById('special-event-note').value.trim();

  const isCup = category === '盃賽';
  const reasonObj = { title, category, location, note, isCup };

  const eventRecord = {
    id: id && !id.startsWith('cup-demo') && !id.startsWith('event-demo') ? id : generateUUID(),
    user_id: state.currentUser?.id || 'admin',
    user_name: '特殊行程',
    leave_date: date,
    leave_type: category,
    session_name: '__SYS_SPECIAL_EVENT__',
    reason: JSON.stringify(reasonObj),
    leave_photo: '',
    makeup_text: '',
    makeup_photo: '',
    makeup_done: false,
    status: '已核准',
    created_at: new Date().toISOString()
  };

  const idx = state.leaves.findIndex(l => l.id === eventRecord.id);
  if (idx !== -1) {
    state.leaves[idx] = { ...state.leaves[idx], ...eventRecord };
  } else {
    state.leaves.push(eventRecord);
  }

  if (supabaseClient) {
    try {
      await supabaseClient.from('team_leaves').upsert([eventRecord]);
    } catch (err) {
      console.warn('Supabase save special event error:', err);
    }
  }

  closeModal('modal-special-event');
  showToast(`已儲存特殊行程：${title}`, 'success');
  renderDashboardSection();
  renderPracticeScheduleCalendar('leaves-schedule-calendar');
  renderEquipmentCalendarBoard('equipment-calendar-board');
}

async function deleteSpecialEvent(id) {
  if (!confirm('確定要刪除此項特殊行程嗎？')) return;
  state.leaves = state.leaves.filter(l => l.id !== id);
  if (supabaseClient && !id.startsWith('cup-demo') && !id.startsWith('event-demo')) {
    try {
      await supabaseClient.from('team_leaves').delete().eq('id', id);
    } catch (err) {
      console.warn('Supabase delete special event error:', err);
    }
  }
  showToast('已刪除特殊行程', 'info');
  renderDashboardSection();
  renderPracticeScheduleCalendar('leaves-schedule-calendar');
  renderEquipmentCalendarBoard('equipment-calendar-board');
}

function renderCupCountdown(containerId = 'dashboard-cup-countdown-bar') {
  const container = document.getElementById(containerId);
  if (!container) return;

  const events = getSpecialEvents();
  const todayStr = getTodayStr();
  const todayDate = new Date(todayStr);

  // 篩選盃賽與近期特殊行程
  const cupEvents = events.filter(e => e.isCup || e.category === '盃賽');
  const otherEvents = events.filter(e => !e.isCup && e.category !== '盃賽');

  // 計算倒數天數
  const cupCountdownList = cupEvents.map(e => {
    const targetDate = new Date(e.date);
    const diffTime = targetDate.getTime() - todayDate.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return { ...e, diffDays };
  }).sort((a, b) => a.diffDays - b.diffDays);

  const isAdmin = state.currentUser?.role === 'admin';

  if (cupCountdownList.length === 0 && otherEvents.length === 0) {
    container.innerHTML = '';
    return;
  }

  container.innerHTML = `
    <div class="bg-matte-card p-4 sm:p-5 rounded-2xl shadow-sm border border-matte-border space-y-3">
      <div class="flex items-center justify-between gap-2 flex-wrap">
        <div class="flex items-center gap-2">
          <span class="p-1.5 rounded-lg bg-[#1c1b18] text-stone-100">
            <i data-lucide="trophy" class="w-4 h-4"></i>
          </span>
          <div>
            <h3 class="font-extrabold text-sm sm:text-base text-matte-ink">🏆 盃賽倒數計時與特殊行程</h3>
            <p class="text-xs text-matte-muted">重要盃賽日程及迎新隊聚行程提醒</p>
          </div>
        </div>
        ${isAdmin ? `
          <button type="button" onclick="openSpecialEventModal()"
            class="px-3 py-1.5 rounded-xl bg-matte-sub hover:bg-[#1c1b18] text-matte-ink hover:text-stone-100 border border-matte-border text-xs font-bold transition flex items-center gap-1.5 shadow-2xs">
            <i data-lucide="plus" class="w-3.5 h-3.5"></i>
            <span>新增行程 / 盃賽</span>
          </button>
        ` : ''}
      </div>

      <!-- 盃賽倒數卡片網格 -->
      <div class="grid grid-cols-1 md:grid-cols-2 gap-3">
        ${cupCountdownList.map(cup => {
          const isUrgent = cup.diffDays >= 0 && cup.diffDays <= 14;
          const isToday = cup.diffDays === 0;
          const isPast = cup.diffDays < 0;

          let badgeText = `D-${cup.diffDays}`;
          let badgeClass = 'bg-[#1c1b18] text-stone-100';
          if (isToday) {
            badgeText = '🔥 今天開打！';
            badgeClass = 'bg-stone-900 text-amber-200 font-extrabold ring-2 ring-stone-400';
          } else if (isPast) {
            badgeText = '已完賽';
            badgeClass = 'bg-stone-300 text-matte-ink';
          } else if (isUrgent) {
            badgeClass = 'bg-[#1c1b18] text-stone-100 ring-2 ring-stone-500';
          }

          return `
            <div class="p-4 rounded-xl bg-matte-sub border ${isUrgent ? 'border-stone-500' : 'border-matte-border'} flex flex-col justify-between space-y-2.5">
              <div class="flex items-start justify-between gap-2">
                <div class="space-y-1">
                  <div class="flex items-center gap-1.5 flex-wrap">
                    <span class="px-2 py-0.5 rounded text-[10px] font-extrabold bg-stone-300 text-matte-ink">🏆 ${escapeHtml(cup.category)}</span>
                    <span class="font-extrabold text-sm sm:text-base text-matte-ink">${escapeHtml(cup.title)}</span>
                  </div>
                  <p class="text-xs text-matte-muted flex items-center gap-2 flex-wrap">
                    <span>📅 ${cup.date}</span>
                    ${cup.location ? `<span>📍 ${escapeHtml(cup.location)}</span>` : ''}
                  </p>
                  ${cup.note ? `<p class="text-[11px] text-matte-ink bg-matte-card px-2 py-1 rounded border border-matte-border mt-1">📝 ${escapeHtml(cup.note)}</p>` : ''}
                </div>
                <div class="text-right shrink-0">
                  <span class="px-3 py-1.5 rounded-xl text-xs sm:text-sm font-extrabold shadow-xs inline-block ${badgeClass}">
                    ${badgeText}
                  </span>
                  ${!isPast && !isToday ? `<span class="block text-[10px] text-matte-muted mt-0.5">${cup.diffDays} 天後</span>` : ''}
                </div>
              </div>
              ${isAdmin && !cup.isDemo ? `
                <div class="flex justify-end gap-2 pt-1 border-t border-matte-border/50">
                  <button type="button" onclick="openSpecialEventModal('${cup.id}')" class="text-[11px] text-matte-muted hover:text-matte-ink font-bold">編輯</button>
                  <button type="button" onclick="deleteSpecialEvent('${cup.id}')" class="text-[11px] text-stone-500 hover:text-stone-800 font-bold">刪除</button>
                </div>
              ` : ''}
            </div>
          `;
        }).join('')}
      </div>

      <!-- 其他特殊行程橫幅 (如迎新聚餐、友誼賽) -->
      ${otherEvents.length > 0 ? `
        <div class="pt-2 border-t border-matte-border space-y-1.5">
          <span class="text-xs font-bold text-matte-muted">🎉 近期其他活動與隊聚：</span>
          <div class="flex flex-wrap gap-2">
            ${otherEvents.map(ev => `
              <div class="px-3 py-1.5 rounded-xl bg-matte-sub border border-matte-border flex items-center gap-2 text-xs">
                <span class="font-extrabold text-matte-ink">${ev.category === '聚餐' ? '🍻' : '📌'} ${escapeHtml(ev.title)}</span>
                <span class="text-matte-muted font-bold">${ev.date}</span>
                ${ev.location ? `<span class="text-matte-muted text-[11px]">(${escapeHtml(ev.location)})</span>` : ''}
                ${isAdmin && !ev.isDemo ? `
                  <button type="button" onclick="deleteSpecialEvent('${ev.id}')" class="text-stone-400 hover:text-stone-700 ml-1">
                    <i data-lucide="x" class="w-3 h-3"></i>
                  </button>
                ` : ''}
              </div>
            `).join('')}
          </div>
        </div>
      ` : ''}
    </div>
  `;
}

function getDateMilestoneBadge(dateStr) {
  if (!dateStr || dateStr.length < 10) return '';
  const d = dateStr.slice(0, 10);

  // 優先檢查是否有特殊行程 / 盃賽
  const specialEv = getSpecialEvents().find(e => e.date === d);
  if (specialEv) {
    if (specialEv.category === '盃賽' || specialEv.isCup) {
      return `🏆 ${specialEv.title}`;
    } else if (specialEv.category === '聚餐') {
      return `🍻 ${specialEv.title}`;
    } else {
      return `📌 ${specialEv.title}`;
    }
  }

  const info = getAcademicTermInfo(d);
  const dates = getAcademicYearDatesConfig(info.academicYear);
  const shortMd = `${Number(d.slice(5, 7))}/${Number(d.slice(8, 10))}`;
  if (d === dates.yearStart) return `🎉 ${info.academicYear}學年始`;
  if (d === dates.sem1Start) return `🎒 ${shortMd}開學`;
  if (d === dates.winterStart) return `❄️ ${shortMd}放寒假`;
  if (d === dates.sem2Start) return `🌱 ${shortMd}下學期開學`;
  if (d === dates.summerStart) return `☀️ ${shortMd}放暑假`;
  if (d === dates.yearEnd) return `🏁 ${info.academicYear}學年終`;
  return '';
}

function getPeriodRecordCount(academicYear, period) {
  let count = 0;
  const dateSet = new Set();
  state.fitness.forEach(f => {
    if (f.target_date && isDateInAcademicPeriod(f.target_date, academicYear, period)) {
      count++;
      dateSet.add(f.target_date);
    }
  });
  state.leaves.forEach(l => {
    if (l.leave_date && !isSystemAcademicConfigRecord(l) && isDateInAcademicPeriod(l.leave_date, academicYear, period)) {
      dateSet.add(l.leave_date);
    }
  });
  return { recordCount: count, activeDaysCount: dateSet.size };
}

function getMonthRecordCountInPeriod(ym, academicYear, period) {
  const dateSet = new Set();
  let fitCount = 0;
  state.fitness.forEach(f => {
    if (f.target_date && f.target_date.startsWith(ym) && isDateInAcademicPeriod(f.target_date, academicYear, period)) {
      fitCount++;
      dateSet.add(f.target_date);
    }
  });
  state.leaves.forEach(l => {
    if (l.leave_date && !isSystemAcademicConfigRecord(l) && l.leave_date.startsWith(ym) && isDateInAcademicPeriod(l.leave_date, academicYear, period)) {
      dateSet.add(l.leave_date);
    }
  });
  return { fitCount, activeDaysCount: dateSet.size };
}

function pickBestDateAndMonthForTerm(academicYear, period) {
  const cfg = getAcademicPeriodConfig(academicYear, period);
  const today = getTodayStr();

  // 收集符合該學年度+期間的所有訓練/請假/排程日期
  const activeDatesSet = new Set();
  state.fitness.forEach(f => {
    if (f.target_date && isDateInAcademicPeriod(f.target_date, academicYear, period)) {
      activeDatesSet.add(f.target_date);
    }
  });
  state.leaves.forEach(l => {
    if (l.leave_date && !isSystemAcademicConfigRecord(l) && isDateInAcademicPeriod(l.leave_date, academicYear, period)) {
      activeDatesSet.add(l.leave_date);
    }
  });
  const sortedDates = Array.from(activeDatesSet).sort((a, b) => b.localeCompare(a));

  if (period === '暑假' && sortedDates.length > 0) {
    // 針對暑假：統計哪個月份擁有最多紀錄（例如 114學年度暑假在 2026-07，115學年度暑假主要在 2026-08）
    const monthCounts = new Map();
    state.fitness.forEach(f => {
      if (f.target_date && isDateInAcademicPeriod(f.target_date, academicYear, period)) {
        const m = f.target_date.slice(0, 7);
        monthCounts.set(m, (monthCounts.get(m) || 0) + 1);
      }
    });
    if (monthCounts.size > 0) {
      const bestYm = Array.from(monthCounts.entries()).sort((a, b) => b[1] - a[1])[0][0];
      const datesInBestMonth = sortedDates.filter(d => d.startsWith(bestYm));
      const bestDate = datesInBestMonth[0] || sortedDates[0];
      return { ym: bestYm, dateStr: bestDate };
    }
  }

  // 若今日剛好在該學年度+期間內，優先定位於今日所在月份
  if (isDateInAcademicPeriod(today, academicYear, period)) {
    return { ym: today.slice(0, 7), dateStr: sortedDates[0] || today };
  }

  if (sortedDates.length > 0) {
    return { ym: sortedDates[0].slice(0, 7), dateStr: sortedDates[0] };
  }

  const fallbackMonth = cfg.months[0] || { ym: today.slice(0, 7), defaultDate: today };
  return { ym: fallbackMonth.ym, dateStr: fallbackMonth.defaultDate };
}

function syncAcademicFilterDropdowns() {
  ensureAcademicPeriodInitialized();
  const years = getAvailableAcademicYears();
  const aySelectIds = ['filter-fitness-ay', 'filter-leave-ay'];
  aySelectIds.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    const opts = years.map(y => `<option value="${y}">${y} 學年</option>`);
    opts.push(`<option value="all">全部學年</option>`);
    el.innerHTML = opts.join('');
    el.value = String(state.selectedAcademicYear);
  });

  const periodSelectIds = ['filter-fitness-period', 'filter-leave-period'];
  periodSelectIds.forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    el.value = String(state.selectedTermPeriod);
  });

  // 更新最上方大標「縮小日期細項篩選按鈕」的文字標籤
  const headerLabelEl = document.getElementById('header-academic-period-label');
  if (headerLabelEl) {
    const ayLabel = state.selectedAcademicYear === 'all' ? '全部學年' : `${state.selectedAcademicYear} 學年`;
    const perLabel = state.selectedTermPeriod === 'all' ? '全學年' : state.selectedTermPeriod;
    headerLabelEl.textContent = `${ayLabel}・${perLabel}`;
  }

  // 若當前大標篩選選單為開啟狀態，即時同步更新選單內容
  if (state.isHeaderAcademicFilterOpen) {
    const content = document.getElementById('header-academic-filter-content');
    if (content) {
      const activeYm = state.activeTab === 'equipment' ? (state.equipmentCalendarMonth || getTodayStr().slice(0, 7)) : (state.scheduleCalendarMonth || getTodayStr().slice(0, 7));
      content.innerHTML = renderAcademicPeriodControlHtml('header', true, activeYm);
      lucide.createIcons();
    }
  }
}

// 點擊最上方大標篩選按鈕，切換展開或收合日期細項選單
function toggleAcademicFilterDropdown(forceState = null) {
  const dropdown = document.getElementById('header-academic-filter-dropdown');
  const btn = document.getElementById('btn-toggle-academic-filter');
  const chevron = document.getElementById('header-academic-chevron');
  if (!dropdown) return;

  const willOpen = forceState !== null ? forceState : dropdown.classList.contains('hidden');
  state.isHeaderAcademicFilterOpen = willOpen;

  if (willOpen) {
    dropdown.classList.remove('hidden');
    if (btn) {
      btn.classList.add('bg-[#1c1b18]', 'text-stone-100');
      btn.classList.remove('bg-matte-sub', 'text-matte-ink');
    }
    if (chevron) {
      chevron.style.transform = 'rotate(180deg)';
    }
    const content = document.getElementById('header-academic-filter-content');
    if (content) {
      const activeYm = state.activeTab === 'equipment' ? (state.equipmentCalendarMonth || getTodayStr().slice(0, 7)) : (state.scheduleCalendarMonth || getTodayStr().slice(0, 7));
      content.innerHTML = renderAcademicPeriodControlHtml('header', true, activeYm);
      lucide.createIcons();
    }
  } else {
    dropdown.classList.add('hidden');
    if (btn) {
      btn.classList.remove('bg-[#1c1b18]', 'text-stone-100');
      btn.classList.add('bg-matte-sub', 'text-matte-ink');
    }
    if (chevron) {
      chevron.style.transform = '';
    }
  }
}

function onChangeAcademicYearSelect(newAy) {
  applyAcademicPeriodSelection(newAy, state.selectedTermPeriod);
}

function onChangeTermPeriodSelect(newPeriod) {
  applyAcademicPeriodSelection(state.selectedAcademicYear, newPeriod);
}

function applyAcademicPeriodSelection(newAy, newPeriod) {
  ensureAcademicPeriodInitialized();
  state.selectedAcademicYear = String(newAy || state.selectedAcademicYear || '115');
  state.selectedTermPeriod = String(newPeriod || state.selectedTermPeriod || '上學期');

  const best = pickBestDateAndMonthForTerm(state.selectedAcademicYear, state.selectedTermPeriod);
  state.scheduleCalendarMonth = best.ym;
  state.equipmentCalendarMonth = best.ym;
  state.selectedAttendanceDate = best.dateStr;
  state.selectedEquipDate = best.dateStr;

  // 同步更新體能矩陣的選取日期（選取該學年度+期間內該球員最新的日期）
  const playerRecsInTerm = state.fitness
    .filter(f =>
      (!state.selectedFitnessPlayer || f.user_name === state.selectedFitnessPlayer) &&
      isDateInAcademicPeriod(f.target_date, state.selectedAcademicYear, state.selectedTermPeriod)
    )
    .sort((a, b) => (b.target_date || '').localeCompare(a.target_date || ''));
  state.selectedFitnessDate = playerRecsInTerm.length > 0 ? playerRecsInTerm[0].target_date : best.dateStr;

  state.editingBatchRuleId = null;
  state.batchScheduleDraft = {
    isDirty: false,
    startDate: '',
    endDate: '',
    weekdays: null,
    type: '',
    practiceTime: '',
    startTime: '',
    endTime: '',
    planNote: ''
  };

  syncAcademicFilterDropdowns();
  renderAll();
}

function selectCalendarMonthDirect(ym) {
  if (!ym) return;
  state.scheduleCalendarMonth = ym;
  state.equipmentCalendarMonth = ym;

  // 從該月份中挑選一個符合目前學年度+期間的日期作為預設選取日
  const matchingDates = [];
  const [y, m] = ym.split('-').map(Number);
  const daysInM = new Date(y, m, 0).getDate();
  for (let d = 1; d <= daysInM; d++) {
    const ds = `${ym}-${String(d).padStart(2, '0')}`;
    if (isDateInAcademicPeriod(ds, state.selectedAcademicYear, state.selectedTermPeriod)) {
      matchingDates.push(ds);
    }
  }
  const activeDatesInMonth = matchingDates.filter(ds =>
    state.fitness.some(f => f.target_date === ds) || state.leaves.some(l => l.leave_date === ds && !isSystemAcademicConfigRecord(l))
  );
  const targetDate = activeDatesInMonth[activeDatesInMonth.length - 1] || matchingDates[0] || `${ym}-01`;
  state.selectedAttendanceDate = targetDate;
  state.selectedEquipDate = targetDate;

  syncAcademicFilterDropdowns();
  renderAll();
}

// 產生共用的「年度（如 114、115）＋ 期間（暑假、上學期、寒假、下學期）」控制列 HTML (圖一選單內容)
function renderAcademicPeriodControlHtml(contextKey = 'calendar', showMonthPills = true, activeYm = '') {
  ensureAcademicPeriodInitialized();
  const years = getAvailableAcademicYears();
  const cfg = getAcademicPeriodConfig(state.selectedAcademicYear, state.selectedTermPeriod);
  const curAy = String(state.selectedAcademicYear);
  const curPer = String(state.selectedTermPeriod);

  const yearOptionsHtml = years.map(y => {
    const selected = curAy === String(y) ? 'selected' : '';
    return `<option value="${y}" ${selected}>${y} 學年</option>`;
  }).join('') + `<option value="all" ${curAy === 'all' ? 'selected' : ''}>全部學年</option>`;

  const periodPillsHtml = ACADEMIC_PERIOD_DEFS.map(p => {
    const isSelected = curPer === p.id;
    const stat = getPeriodRecordCount(curAy, p.id);
    return `
      <button type="button" onclick="onChangeTermPeriodSelect('${p.id}')"
        class="px-3 py-1.5 rounded-xl text-xs font-extrabold transition flex items-center gap-1.5 ${
          isSelected
            ? 'bg-[#1c1b18] text-stone-100 shadow-xs ring-2 ring-stone-500'
            : 'bg-matte-card hover:bg-stone-300 text-matte-ink border border-matte-border'
        }">
        <span>${p.icon} ${p.label}</span>
        ${stat.activeDaysCount > 0 ? `
          <span class="px-1.5 py-0.2 rounded text-[10px] ${
            isSelected ? 'bg-stone-700 text-stone-100' : 'bg-stone-300 text-matte-ink'
          }">${stat.activeDaysCount}天</span>
        ` : ''}
      </button>
    `;
  }).join('') + `
    <button type="button" onclick="onChangeTermPeriodSelect('all')"
      class="px-2.5 py-1.5 rounded-xl text-xs font-bold transition ${
        curPer === 'all'
          ? 'bg-[#1c1b18] text-stone-100 shadow-xs ring-2 ring-stone-500'
          : 'bg-matte-card hover:bg-stone-300 text-matte-muted hover:text-matte-ink border border-matte-border'
      }">
      全學年
    </button>
  `;

  const monthPillsHtml = showMonthPills ? `
    <div class="flex items-center gap-1.5 flex-wrap pt-2 border-t border-stone-300/80">
      <span class="text-[11px] font-extrabold text-matte-muted shrink-0">🗓️ 月份快速切換：</span>
      ${cfg.months.map(m => {
        const isCurrentMonth = activeYm === m.ym;
        const mStat = getMonthRecordCountInPeriod(m.ym, curAy, curPer);
        return `
          <button type="button" onclick="selectCalendarMonthDirect('${m.ym}')"
            class="px-2.5 py-1 rounded-lg text-xs font-bold transition flex items-center gap-1 ${
              isCurrentMonth
                ? 'bg-[#1c1b18] text-stone-100 shadow-2xs'
                : 'bg-matte-card hover:bg-stone-300 text-matte-ink border border-matte-border'
            }">
            <span>${escapeHtml(m.shortLabel)}</span>
            ${mStat.activeDaysCount > 0 ? `<span class="px-1 py-0.1 rounded text-[10px] ${isCurrentMonth ? 'bg-stone-700 text-stone-200' : 'bg-stone-200 text-matte-ink'}">${mStat.activeDaysCount}天</span>` : ''}
          </button>
        `;
      }).join('')}
    </div>
  ` : '';

  const curPlan = getTermLongTermPlanConfig(curAy, curPer);
  const rulesStr = (curPlan.rules || []).map(r => `每週${(r.weekdays || []).map(w => ['日','一','二','三','四','五','六'][Number(w)]).join('、')} ${r.type} (${r.practiceTime})`).join(' ｜ ');
  const hasPlan = Boolean(curPlan.planNote || rulesStr);

  return `
    <div class="p-3.5 sm:p-4 rounded-2xl bg-matte-sub border border-matte-border space-y-3">
      <!-- 頂部標題列與收合選單按鈕 -->
      <div class="flex items-center justify-between border-b border-stone-300/80 pb-2">
        <div class="flex items-center gap-2">
          <span class="p-1 rounded-lg bg-[#1c1b18] text-stone-100">
            <i data-lucide="calendar" class="w-3.5 h-3.5"></i>
          </span>
          <span class="text-xs sm:text-sm font-extrabold text-matte-ink">學年度與期間篩選（全隊各功能列同步）</span>
        </div>
        <button type="button" onclick="toggleAcademicFilterDropdown(false)"
          class="px-2.5 py-1 rounded-xl bg-matte-card hover:bg-stone-300 text-matte-ink text-xs font-bold border border-matte-border transition flex items-center gap-1 shadow-2xs">
          <i data-lucide="x" class="w-3.5 h-3.5"></i>
          <span>收合選單</span>
        </button>
      </div>

      <div class="flex flex-col lg:flex-row lg:items-center justify-between gap-2">
        <div class="flex flex-wrap items-center gap-2">
          <div class="flex items-center gap-1.5">
            <label class="text-xs font-extrabold text-matte-ink shrink-0">🎓 年度</label>
            <select onchange="onChangeAcademicYearSelect(this.value)"
              class="px-2.5 py-1.5 rounded-xl bg-matte-card border border-matte-border text-xs sm:text-sm font-extrabold text-matte-ink focus:outline-none focus:ring-2 focus:ring-stone-700">
              ${yearOptionsHtml}
            </select>
          </div>
          <div class="flex flex-wrap items-center gap-1.5">
            ${periodPillsHtml}
          </div>
        </div>
        <span class="text-[11px] font-bold text-matte-muted shrink-0">期間：${escapeHtml(cfg.rangeText || cfg.aySpanText)}</span>
      </div>

      ${hasPlan ? `
        <div class="p-2 rounded-xl bg-matte-card border border-matte-border flex items-center gap-1.5 flex-wrap text-xs">
          <span class="px-2 py-0.5 rounded bg-[#1c1b18] text-stone-100 text-[10px] font-extrabold shrink-0">📋 固定練球</span>
          ${rulesStr ? `<span class="font-extrabold text-matte-ink">${escapeHtml(rulesStr)}</span>` : ''}
          ${curPlan.planNote ? `<span class="text-matte-muted font-bold">· ${escapeHtml(curPlan.planNote)}</span>` : ''}
        </div>
      ` : ''}

      ${monthPillsHtml}
    </div>
  `;
}

// 取得所有一般球員帳號 (排除管理者，管理者無須被指派體能或補體能)
function getPlayerUsers() {
  return state.users.filter(u => u.role !== 'admin');
}

// 解析單日排程詳細資訊（含排程類型：練球 / 體能 / 練球+體能 / 放假 / none、練習時間、是否更改時間、備註）
function getDateScheduleDetails(dateStr) {
  const explicit = getScheduleRecords().find(r => r.leave_date === dateStr);
  if (explicit) {
    const rawType = (explicit.leave_type === '無' || explicit.leave_type === 'none') ? 'none' : (explicit.leave_type || 'none');
    let practiceTime = '';
    let isTimeChanged = false;
    let note = '';
    const rawReason = (explicit.reason || '').trim();
    if (rawReason.startsWith('{')) {
      try {
        const parsed = JSON.parse(rawReason);
        practiceTime = parsed.practiceTime || '';
        isTimeChanged = Boolean(parsed.isTimeChanged);
        note = parsed.note || '';
      } catch (e) {
        note = rawReason;
      }
    } else if (rawReason && !rawReason.startsWith('管理者排定：')) {
      note = rawReason;
    }
    return {
      type: rawType,
      isHoliday: rawType === '放假',
      practiceTime,
      isTimeChanged,
      note,
      isExplicit: true
    };
  }

  const hasFit = state.fitness.some(f => f.target_date === dateStr && !(f.task_name || '').includes('補體能'));
  const hasLeave = getRealLeaves().some(l => l.leave_date === dateStr);
  let inferredType = 'none';
  if (hasFit && hasLeave) inferredType = '練球+體能';
  else if (hasFit) inferredType = '體能';
  else if (hasLeave) inferredType = '練球';

  return {
    type: inferredType,
    isHoliday: false,
    practiceTime: '',
    isTimeChanged: false,
    note: '',
    isExplicit: false
  };
}

function getDateScheduleType(dateStr) {
  return getDateScheduleDetails(dateStr).type;
}

// 判斷當日是否為練球或訓練日（沒有練習的日子不需要借器材）
function isPracticeDay(dateStr) {
  if (!dateStr) return false;
  const type = getDateScheduleType(dateStr);
  return type === '練球' || type === '練球+體能' || type === '體能';
}

// ----------------------------------------------------------------------------
// 器材人數需求設定（依照固定排程各區間時段設定 + 單日自訂人數微調）
// ----------------------------------------------------------------------------
function getEquipmentConfig() {
  const rec = getEquipmentConfigRecord();
  if (rec && rec.reason) {
    try {
      const parsed = JSON.parse(rec.reason);
      return {
        defaultBorrowQuota: Math.max(0, Number(parsed.defaultBorrowQuota) ?? 1),
        defaultReturnQuota: Math.max(0, Number(parsed.defaultReturnQuota) ?? 1),
        ruleQuotas: parsed.ruleQuotas || {},
        dailyQuotas: parsed.dailyQuotas || {}
      };
    } catch (e) {
      console.warn('Parse equip config error', e);
    }
  }
  return {
    defaultBorrowQuota: 1,
    defaultReturnQuota: 1,
    ruleQuotas: {},
    dailyQuotas: {}
  };
}

// 取得指定固定排程規則之借還器材人數（依據 ruleQuotas 或 rule 本身設定，體能預設0人免借）
function getEquipmentQuotaForRule(ruleId, ruleObj = null) {
  const cfg = getEquipmentConfig();
  if (ruleId && cfg.ruleQuotas && cfg.ruleQuotas[ruleId]) {
    const rq = cfg.ruleQuotas[ruleId];
    return {
      borrow: Math.max(0, Number(rq.borrow) ?? 1),
      return: Math.max(0, Number(rq.return) ?? 1)
    };
  }
  if (ruleObj) {
    if (ruleObj.borrowQuota !== undefined || ruleObj.returnQuota !== undefined) {
      return {
        borrow: Math.max(0, Number(ruleObj.borrowQuota) ?? 1),
        return: Math.max(0, Number(ruleObj.returnQuota) ?? 1)
      };
    }
    if (ruleObj.type === '體能') {
      return { borrow: 0, return: 0 };
    }
  }
  return {
    borrow: Math.max(0, Number(cfg.defaultBorrowQuota) ?? 1),
    return: Math.max(0, Number(cfg.defaultReturnQuota) ?? 1)
  };
}

// 根據日期搜尋對應的固定練球計畫規則 (圖二已排定固定練球區間)
function findMatchingScheduleRuleForDate(dateStr) {
  if (!dateStr) return null;
  const termInfo = getAcademicTermInfo(dateStr);
  const curPlan = getTermLongTermPlanConfig(termInfo.academicYear, termInfo.period);
  const curRules = curPlan.rules || [];
  if (curRules.length === 0) return null;

  // 1. 優先比對排程紀錄中標註的 ruleId
  const explicit = getScheduleRecords().find(r => r.leave_date === dateStr);
  if (explicit && explicit.reason && explicit.reason.startsWith('{')) {
    try {
      const parsed = JSON.parse(explicit.reason);
      if (parsed.ruleId) {
        const matched = curRules.find(r => r.id === parsed.ruleId);
        if (matched) return matched;
      }
    } catch (e) {}
  }

  // 2. 依照練球區間、星期幾與訓練類型比對
  const [y, m, d] = dateStr.split('-').map(Number);
  const wk = new Date(y, m - 1, d).getDay();
  const explicitType = explicit ? explicit.leave_type : null;

  const matched = curRules.find(r => {
    if (r.startDate && r.endDate && (dateStr < r.startDate || dateStr > r.endDate)) return false;
    if (Array.isArray(r.weekdays) && !r.weekdays.map(Number).includes(wk)) return false;
    if (explicitType && explicitType !== 'none' && explicitType !== '無') {
      return r.type === explicitType;
    }
    return true;
  });

  return matched || null;
}

// 取得單日器材需求人數（單日自訂 > 固定排程規則設定 > 全隊預設人數）
function getEquipmentQuotaForDate(dateStr) {
  const cfg = getEquipmentConfig();

  // 1. 單日自訂人數覆蓋 (單日特殊調整優先)
  if (cfg.dailyQuotas && cfg.dailyQuotas[dateStr]) {
    const dq = cfg.dailyQuotas[dateStr];
    return {
      borrowQuota: Math.max(0, Number(dq.borrow) ?? 1),
      returnQuota: Math.max(0, Number(dq.return) ?? 1),
      isCustom: true,
      ruleName: '單日自訂人數',
      ruleId: null
    };
  }

  // 2. 依照圖二排定的固定練球區間比對人數
  const rule = findMatchingScheduleRuleForDate(dateStr);
  if (rule) {
    const rq = getEquipmentQuotaForRule(rule.id, rule);
    return {
      borrowQuota: rq.borrow,
      returnQuota: rq.return,
      isCustom: false,
      ruleName: `${rule.type} (${rule.practiceTime || '固定時段'})`,
      ruleId: rule.id
    };
  }

  // 3. 未匹配固定排程時使用全隊預設人數
  return {
    borrowQuota: Math.max(0, Number(cfg.defaultBorrowQuota) ?? 1),
    returnQuota: Math.max(0, Number(cfg.defaultReturnQuota) ?? 1),
    isCustom: false,
    ruleName: '全隊預設',
    ruleId: null
  };
}

async function persistEquipmentConfig(cfg) {
  const existing = getEquipmentConfigRecord();
  const recId = existing ? existing.id : generateUUID();
  const configRecord = {
    id: recId,
    user_id: state.currentUser?.id || 'admin',
    user_name: '器材設定',
    leave_date: '2099-12-31',
    leave_type: '設定',
    session_name: '__SYS_EQUIP_CONFIG__',
    reason: JSON.stringify(cfg),
    leave_photo: '',
    makeup_text: '',
    makeup_photo: '',
    makeup_done: false,
    status: '已核准',
    created_at: new Date().toISOString()
  };

  const idx = state.leaves.findIndex(l => l.id === recId);
  if (idx !== -1) {
    state.leaves[idx] = configRecord;
  } else {
    state.leaves.push(configRecord);
  }

  if (state.isSupabaseReady) {
    try {
      await supabaseClient.from('team_leaves').upsert([configRecord]);
    } catch (err) {
      console.warn('Persist equip config error:', err);
    }
  }
  await notifyRealtimePeers();
}

async function saveRuleEquipmentQuota(ruleId, borrowQuota, returnQuota) {
  const cfg = getEquipmentConfig();
  if (!cfg.ruleQuotas) cfg.ruleQuotas = {};
  const b = Math.max(0, Number(borrowQuota) || 0);
  const r = Math.max(0, Number(returnQuota) || 0);
  cfg.ruleQuotas[ruleId] = { borrow: b, return: r };
  await persistEquipmentConfig(cfg);

  // 同步更新固定計畫中的 rule 物件
  const termCfg = getAcademicPeriodConfig(state.selectedAcademicYear, state.selectedTermPeriod);
  const curAy = termCfg.numericYear || 115;
  const curPer = termCfg.period === 'all' ? '上學期' : termCfg.period;
  const curPlan = getTermLongTermPlanConfig(curAy, curPer);
  if (curPlan && Array.isArray(curPlan.rules)) {
    const target = curPlan.rules.find(x => x.id === ruleId);
    if (target) {
      target.borrowQuota = b;
      target.returnQuota = r;
      await saveTermLongTermPlan(curAy, curPer, curPlan.planNote, curPlan.rules);
    }
  }

  showToast(`已更新固定排程器材人數：借 ${b} 人 / 還 ${r} 人`, 'success');
  renderAll();
}

async function saveAllRuleEquipmentQuotas() {
  const termCfg = getAcademicPeriodConfig(state.selectedAcademicYear, state.selectedTermPeriod);
  const curAy = termCfg.numericYear || 115;
  const curPer = termCfg.period === 'all' ? '上學期' : termCfg.period;
  const curPlan = getTermLongTermPlanConfig(curAy, curPer);
  const curRules = (curPlan.rules || []).map((r, idx) => ({
    id: r.id || `rule_${curAy}_${curPer}_${idx}_${(r.weekdays || []).join('')}`,
    ...r
  }));

  if (curRules.length === 0) {
    showToast('目前學期尚無固定練球區間可儲存！', 'info');
    return;
  }

  const cfg = getEquipmentConfig();
  if (!cfg.ruleQuotas) cfg.ruleQuotas = {};

  let count = 0;
  curRules.forEach(rule => {
    const bInput = document.getElementById(`rule-borrow-quota-${rule.id}`);
    const rInput = document.getElementById(`rule-return-quota-${rule.id}`);
    if (bInput && rInput) {
      const b = Math.max(0, Number(bInput.value) || 0);
      const r = Math.max(0, Number(rInput.value) || 0);
      cfg.ruleQuotas[rule.id] = { borrow: b, return: r };
      rule.borrowQuota = b;
      rule.returnQuota = r;
      count++;
    }
  });

  await persistEquipmentConfig(cfg);
  await saveTermLongTermPlan(curAy, curPer, curPlan.planNote, curRules);

  showToast(`已成功儲存 ${count} 筆固定排程借還器材人數！`, 'success');
  renderAll();
}

async function saveDefaultEquipmentQuota(defaultBorrow, defaultReturn) {
  const cfg = getEquipmentConfig();
  cfg.defaultBorrowQuota = Math.max(0, Number(defaultBorrow) || 0);
  cfg.defaultReturnQuota = Math.max(0, Number(defaultReturn) || 0);
  await persistEquipmentConfig(cfg);
  showToast(`已更新全隊預設器材人數：借 ${cfg.defaultBorrowQuota} 人 / 還 ${cfg.defaultReturnQuota} 人`, 'success');
  renderAll();
}

async function saveDailyEquipmentQuota(dateStr, borrowQuota, returnQuota) {
  const cfg = getEquipmentConfig();
  if (!cfg.dailyQuotas) cfg.dailyQuotas = {};
  cfg.dailyQuotas[dateStr] = {
    borrow: Math.max(0, Number(borrowQuota) || 0),
    return: Math.max(0, Number(returnQuota) || 0)
  };
  await persistEquipmentConfig(cfg);
  showToast(`已儲存 ${dateStr} 當日器材需求人數：借 ${borrowQuota} 人 / 還 ${returnQuota} 人`, 'success');
  renderAll();
}

async function resetDailyEquipmentQuota(dateStr) {
  const cfg = getEquipmentConfig();
  if (cfg.dailyQuotas && cfg.dailyQuotas[dateStr]) {
    delete cfg.dailyQuotas[dateStr];
    await persistEquipmentConfig(cfg);
    showToast(`已恢復 ${dateStr} 為固定排程需求人數`, 'info');
    renderAll();
  }
}

function getDateEquipmentStatus(dateStr) {
  const recs = getEquipmentRecords().filter(r => r.leave_date === dateStr);
  const quota = getEquipmentQuotaForDate(dateStr);
  const borrowers = [];
  const returners = [];

  recs.forEach(r => {
    if (r.leave_type === '借還器材') {
      borrowers.push({ user_id: r.user_id, user_name: r.user_name, recordId: r.id, mode: '借還器材' });
      returners.push({ user_id: r.user_id, user_name: r.user_name, recordId: r.id, mode: '借還器材' });
    } else if (r.leave_type === '借器材') {
      borrowers.push({ user_id: r.user_id, user_name: r.user_name, recordId: r.id, mode: '借器材' });
    } else if (r.leave_type === '還器材') {
      returners.push({ user_id: r.user_id, user_name: r.user_name, recordId: r.id, mode: '還器材' });
    }
  });

  const borrowQuota = quota.borrowQuota;
  const returnQuota = quota.returnQuota;
  const needsEquipment = (borrowQuota > 0 || returnQuota > 0);
  const canBorrow = needsEquipment && (borrowers.length < borrowQuota);
  const canReturn = needsEquipment && (returners.length < returnQuota);

  const borrower = borrowers.length > 0 ? borrowers[0] : null;
  const returner = returners.length > 0 ? returners[0] : null;

  return {
    borrowers,
    returners,
    borrowQuota,
    returnQuota,
    needsEquipment,
    isCustomQuota: quota.isCustom,
    ruleName: quota.ruleName || '',
    borrowRemaining: Math.max(0, borrowQuota - borrowers.length),
    returnRemaining: Math.max(0, returnQuota - returners.length),
    canBorrow,
    canReturn,
    borrower,
    returner,
    rawRecords: recs
  };
}

function getMonthlyEquipmentCounts(yearMonth, isAllTime = true) {
  const ym = yearMonth || getTodayStr().slice(0, 7);
  const countsMap = new Map();

  // 排除管理者，管理者自己不需要借器材，不計入平均
  getPlayerUsers().forEach(u => {
    // 歷史給定累計資料（1是借、2是還，共 67 次）直接作為全隊累計基準，不佔用日曆格子
    const base = isAllTime ? (HISTORICAL_EQUIPMENT_BASELINES[u.name] || { borrow: 0, return: 0 }) : { borrow: 0, return: 0 };
    countsMap.set(u.name, {
      user: u,
      count: (base.borrow || 0) + (base.return || 0),
      borrowCount: base.borrow || 0,
      returnCount: base.return || 0,
      dates: []
    });
  });

  // 日曆上之後新增的登記紀錄（真實現行借還，計入日期）
  const recs = isAllTime
    ? getEquipmentRecords()
    : getEquipmentRecords().filter(r => (r.leave_date || '').startsWith(ym));

  recs.sort((a, b) => (a.leave_date || '').localeCompare(b.leave_date || ''));

  recs.forEach(r => {
    const d = r.leave_date;
    const item = countsMap.get(r.user_name);
    if (!item) return;

    const dateStr = d ? `${Number(d.slice(5, 7))}/${Number(d.slice(8, 10))}` : '';

    if (r.leave_type === '借還器材') {
      item.count += 2;
      item.borrowCount += 1;
      item.returnCount += 1;
      if (dateStr) item.dates.push(`${dateStr}(借+還)`);
    } else if (r.leave_type === '借器材') {
      item.count += 1;
      item.borrowCount += 1;
      if (dateStr) item.dates.push(`${dateStr}(借)`);
    } else if (r.leave_type === '還器材') {
      item.count += 1;
      item.returnCount += 1;
      if (dateStr) item.dates.push(`${dateStr}(還)`);
    }
  });

  return Array.from(countsMap.values());
}



// 取得所有一般球員帳號 (排除管理者，管理者無須被指派體能或補體能)
function getPlayerUsers_unused() { return []; }

// 全體隊員歷史累計借還器材基準次數（僅計入全隊累計次數與平均，不佔用日曆日程）
