// 本機備援存取
const LOCAL_STORAGE_KEY = 'vb_team_mgmt_cache_v5';
const SESSION_USER_KEY = 'vb_team_mgmt_current_user_v4';

function saveLocalCache() {
  try {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify({
      users: state.users,
      fitness: state.fitness,
      fees: state.fees,
      leaves: state.leaves,
      finances: state.finances
    }));
  } catch (e) {
    console.warn('Local cache save warning:', e);
  }
}

// 將舊名稱「凱樂」自動歸一合併為「凱勒」，並移除重複帳號
function normalizeMergedRosterInMemory() {
  let kailerUser = state.users.find(u => u.name === '凱勒');
  const kaileUsers = state.users.filter(u => u.name === '凱樂');

  if (!kailerUser && kaileUsers.length > 0) {
    kaileUsers[0].name = '凱勒';
    kailerUser = kaileUsers[0];
  }

  // 若同時有多個凱勒/凱樂帳號，只保留一個凱勒帳號
  const seenKailer = { done: false };
  state.users = state.users.filter(u => {
    if (u.name === '凱樂') return false;
    if (u.name === '凱勒') {
      if (seenKailer.done) return false;
      seenKailer.done = true;
      kailerUser = u;
      return true;
    }
    return true;
  });

  const kailerId = kailerUser ? kailerUser.id : null;

  state.fitness.forEach(f => {
    if (f.user_name === '凱樂') {
      f.user_name = '凱勒';
      if (kailerId) f.user_id = kailerId;
    } else if (f.user_name === '凱勒' && kailerId) {
      f.user_id = kailerId;
    }
  });

  state.fees.forEach(f => {
    if (f.user_name === '凱樂') {
      f.user_name = '凱勒';
      if (kailerId) f.user_id = kailerId;
    } else if (f.user_name === '凱勒' && kailerId) {
      f.user_id = kailerId;
    }
  });

  state.leaves.forEach(l => {
    if (l.user_name === '凱樂') {
      l.user_name = '凱勒';
      if (kailerId) l.user_id = kailerId;
    } else if (l.user_name === '凱勒' && kailerId) {
      l.user_id = kailerId;
    }
  });
}

function loadLocalCache() {
  try {
    const raw = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && Array.isArray(parsed.users) && parsed.users.length > 0) {
        state.users = parsed.users;
        state.fitness = parsed.fitness || [];
        state.fees = parsed.fees || [];
        state.leaves = parsed.leaves || [];
        state.finances = parsed.finances || [];
        normalizeMergedRosterInMemory();
        ensureOfficialMembersAndEquipment();
        return;
      }
    }
  } catch (e) {
    console.warn('Local cache load warning:', e);
  }
  const seed = getDefaultSeedData();
  state.users = seed.users;
  state.fitness = seed.fitness;
  state.fees = seed.fees;
  state.leaves = seed.leaves;
  state.finances = seed.finances;
  normalizeMergedRosterInMemory();
  ensureOfficialMembersAndEquipment();
  saveLocalCache();
}

// ============================================================================
// 圖片壓縮與預覽處理 (支援手機拍照/選圖直接轉成輕量 Base64 存入 Supabase)
// ============================================================================

function compressImageToDataUrl(file, maxWidth = 800, quality = 0.72) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let width = img.width;
        let height = img.height;
        if (width > maxWidth) {
          height = Math.round((height * maxWidth) / width);
          width = maxWidth;
        }
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL('image/jpeg', quality));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

async function handlePhotoPreview(inputEl, wrapId, imgId) {
  const file = inputEl.files && inputEl.files[0];
  if (!file) return;
  try {
    const dataUrl = await compressImageToDataUrl(file);
    photoBuffer[inputEl.id] = dataUrl;
    const wrap = document.getElementById(wrapId);
    const img = document.getElementById(imgId);
    if (img) img.src = dataUrl;
    if (wrap) wrap.classList.remove('hidden');
  } catch (err) {
    showToast('圖片處理失敗，請換一張圖片試試', 'error');
  }
}

function clearPhotoInput(inputId, wrapId, imgId) {
  photoBuffer[inputId] = '';
  const input = document.getElementById(inputId);
  const wrap = document.getElementById(wrapId);
  const img = document.getElementById(imgId);
  if (input) input.value = '';
  if (img) img.src = '';
  if (wrap) wrap.classList.add('hidden');
}

function openLightbox(src, caption = '照片檢視') {
  if (!src) return;
  const modal = document.getElementById('modal-lightbox');
  const img = document.getElementById('lightbox-img');
  const cap = document.getElementById('lightbox-caption');
  if (img) img.src = src;
  if (cap) cap.textContent = caption;
  if (modal) modal.classList.remove('hidden');
}

// 將文字中的網址自動轉成可點擊連結
function renderTextWithLinks(text) {
  if (!text) return '<span class="italic text-matte-muted">尚未填寫</span>';
  const escaped = escapeHtml(text);
  const urlRegex = /(https?:\/\/[^\s<]+)/g;
  return escaped.replace(urlRegex, (url) => {
    return `<a href="${url}" target="_blank" rel="noopener noreferrer" class="underline font-bold text-matte-ink hover:opacity-75 break-all">🔗 ${url}</a>`;
  });
}

// ============================================================================
// Supabase 雲端資料讀取與即時同步
// ============================================================================

async function fetchAllFromSupabase(showSpin = false) {
  if (showSpin) {
    const icon = document.getElementById('sync-spin-icon');
    if (icon) icon.classList.add('animate-spin');
  }

  try {
    const { data: usersData, error: usersErr } = await supabaseClient
      .from('team_users')
      .select('*')
      .order('created_at', { ascending: true });

    if (usersErr) {
      state.isSupabaseReady = false;
      updateConnectionIndicators(false);
      if (state.users.length === 0) {
        loadLocalCache();
        renderAll();
      }
      return false;
    }

    state.isSupabaseReady = true;

    if (!usersData || usersData.length === 0 || !usersData.some(u => u.username === 'player001')) {
      await seedInitialDataToSupabase();
      return await fetchAllFromSupabase(false);
    }

    const [fitRes, feeRes, leaveRes, finRes] = await Promise.all([
      supabaseClient.from('team_fitness').select('*').order('target_date', { ascending: false }).order('updated_at', { ascending: false }),
      supabaseClient.from('team_fees').select('*').order('due_date', { ascending: false }).order('updated_at', { ascending: false }),
      supabaseClient.from('team_leaves').select('*').order('leave_date', { ascending: false }).order('created_at', { ascending: false }),
      supabaseClient.from('team_finances').select('*').order('created_at', { ascending: false })
    ]);

    if (!fitRes.data || !fitRes.data.some(f => f.id === 'c0000000-0000-4000-8000-000000000001')) {
      await seedHistoricalFitnessToSupabase(usersData || []);
      const refreshedFit = await supabaseClient.from('team_fitness').select('*').order('target_date', { ascending: false }).order('updated_at', { ascending: false });
      fitRes.data = refreshedFit.data || fitRes.data;
    }

    const prevFingerprint = `${state.users.length}_${state.fitness.length}_${state.fees.length}_${state.leaves.length}_${state.finances.length}_${state.leaves.slice(0, 20).map(l => l.id + (l.updated_at || l.created_at || '')).join(',')}`;

    state.users = usersData || [];
    state.fitness = fitRes.data || [];
    state.fees = feeRes.data || [];
    state.leaves = leaveRes.data || [];
    state.finances = finRes.data || [];

    // 若雲端仍有舊的「凱樂」帳號或紀錄，自動合併歸一為「凱勒」並同步回 Supabase
    const hasOldKaile =
      state.users.some(u => u.name === '凱樂') ||
      state.users.filter(u => u.name === '凱勒').length > 1 ||
      state.fitness.some(f => f.user_name === '凱樂') ||
      state.fees.some(f => f.user_name === '凱樂') ||
      state.leaves.some(l => l.user_name === '凱樂');

    normalizeMergedRosterInMemory();
    await ensureOfficialMembersAndEquipment();

    if (hasOldKaile && state.isSupabaseReady) {
      const kailerUser = state.users.find(u => u.name === '凱勒');
      const kailerId = kailerUser ? kailerUser.id : null;
      try {
        await Promise.all([
          supabaseClient.from('team_fitness').update({ user_name: '凱勒', ...(kailerId ? { user_id: kailerId } : {}) }).eq('user_name', '凱樂'),
          supabaseClient.from('team_fees').update({ user_name: '凱勒', ...(kailerId ? { user_id: kailerId } : {}) }).eq('user_name', '凱樂'),
          supabaseClient.from('team_leaves').update({ user_name: '凱勒', ...(kailerId ? { user_id: kailerId } : {}) }).eq('user_name', '凱樂')
        ]);
        if (kailerId) {
          await supabaseClient.from('team_users').delete().eq('name', '凱樂').neq('id', kailerId);
        }
      } catch (e) {
        console.warn('Merge 凱樂 -> 凱勒 sync warning:', e);
      }
    }

    if (state.currentUser) {
      const updatedMe = state.users.find(u => u.id === state.currentUser.id || u.username === state.currentUser.username);
      if (updatedMe) {
        state.currentUser = updatedMe;
        sessionStorage.setItem(SESSION_USER_KEY, JSON.stringify(updatedMe));
      }
    }

    const newFingerprint = `${state.users.length}_${state.fitness.length}_${state.fees.length}_${state.leaves.length}_${state.finances.length}_${state.leaves.slice(0, 20).map(l => l.id + (l.updated_at || l.created_at || '')).join(',')}`;

    saveLocalCache();
    updateConnectionIndicators(true);
    const hasDataChanged = !state._lastSyncedFingerprint || state._lastSyncedFingerprint !== newFingerprint;
    state._lastSyncedFingerprint = newFingerprint;
    if (showSpin || hasDataChanged) {
      renderAll();
    }
    return true;
  } catch (err) {
    console.error('Supabase fetch error:', err);
    state.isSupabaseReady = false;
    updateConnectionIndicators(false);
    if (state.users.length === 0) {
      loadLocalCache();
      renderAll();
    }
    return false;
  } finally {
    if (showSpin) {
      setTimeout(() => {
        const icon = document.getElementById('sync-spin-icon');
        if (icon) icon.classList.remove('animate-spin');
      }, 400);
    }
  }
}

async function seedHistoricalFitnessToSupabase(usersList = []) {
  try {
    const seed = getDefaultSeedData();
    const userByName = {};
    usersList.forEach(u => {
      if (u && u.name) userByName[u.name] = u.id;
    });
    const fitnessPayload = seed.fitness.map(f => ({
      ...f,
      user_id: userByName[f.user_name] || null
    }));
    await supabaseClient.from('team_fitness').upsert(fitnessPayload, { onConflict: 'id' });
  } catch (e) {
    console.warn('Seed historical fitness warning:', e);
  }
}

async function seedInitialDataToSupabase() {
  try {
    const seed = getDefaultSeedData();
    await supabaseClient.from('team_users').delete().in('username', ['admin', 'player1', 'player2', 'player3']);
    const { data: upsertedUsers } = await supabaseClient.from('team_users').upsert(seed.users, { onConflict: 'username' }).select('*');
    await supabaseClient.from('team_finances').upsert(seed.finances, { onConflict: 'id' });
    await seedHistoricalFitnessToSupabase(upsertedUsers || seed.users);
  } catch (e) {
    console.warn('Seed initial data warning:', e);
  }
}

function setupRealtimeSubscriptions() {
  if (state.realtimeChannel) {
    supabaseClient.removeChannel(state.realtimeChannel);
  }

  const channel = supabaseClient.channel('vb-team-realtime-channel', {
    config: {
      broadcast: { self: false }
    }
  });

  channel.on(
    'postgres_changes',
    { event: '*', schema: 'public' },
    () => {
      fetchAllFromSupabase(false);
    }
  );

  channel.on(
    'broadcast',
    { event: 'data-updated' },
    (payload) => {
      if (state.isSupabaseReady) {
        fetchAllFromSupabase(false);
      } else if (payload && payload.payload && payload.payload.snapshot) {
        const snap = payload.payload.snapshot;
        state.users = snap.users || state.users;
        state.fitness = snap.fitness || state.fitness;
        state.fees = snap.fees || state.fees;
        state.leaves = snap.leaves || state.leaves;
        state.finances = snap.finances || state.finances;
        saveLocalCache();
        renderAll();
      }
    }
  );

  channel.subscribe();
  state.realtimeChannel = channel;

  if (state.pollTimer) clearInterval(state.pollTimer);
  state.pollTimer = setInterval(() => {
    if (document.visibilityState === 'visible') {
      fetchAllFromSupabase(false);
    }
  }, 6000);

  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') {
      fetchAllFromSupabase(false);
    }
  });
}

async function notifyRealtimePeers() {
  saveLocalCache();
  if (state.realtimeChannel) {
    try {
      await state.realtimeChannel.send({
        type: 'broadcast',
        event: 'data-updated',
        payload: {
          timestamp: Date.now(),
          snapshot: state.isSupabaseReady ? null : {
            users: state.users,
            fitness: state.fitness,
            fees: state.fees,
            leaves: state.leaves,
            finances: state.finances
          }
        }
      });
    } catch (e) {
      console.warn('Broadcast send warning:', e);
    }
  }
}

function updateConnectionIndicators(isCloudConnected) {
  const nowStr = new Date().toLocaleTimeString('zh-TW', { hour12: false });
  const syncTimeEl = document.getElementById('last-sync-time');
  if (syncTimeEl) {
    syncTimeEl.textContent = isCloudConnected ? `雲端同步 ${nowStr}` : `即時快取 ${nowStr}`;
  }

  const banner = document.getElementById('supabase-setup-banner');
  const authDot = document.getElementById('auth-db-dot');
  const authStatus = document.getElementById('auth-db-status');
  const sideDot = document.getElementById('sidebar-live-dot');
  const sideText = document.getElementById('sidebar-live-text');
  const mobDot = document.getElementById('mobile-live-dot');
  const mobText = document.getElementById('mobile-live-text');
  const modalBox = document.getElementById('sql-modal-status-box');
  const modalTitle = document.getElementById('sql-modal-status-title');

  if (isCloudConnected) {
    if (banner) banner.classList.add('hidden');
    [authDot, sideDot, mobDot].forEach(el => {
      if (el) el.className = 'w-2 h-2 rounded-full bg-stone-200 live-dot shrink-0';
    });
    if (authStatus) authStatus.textContent = 'Supabase 雲端資料庫即時連線中';
    if (sideText) sideText.textContent = `Supabase 雲端即時同步中 ${nowStr}`;
    if (mobText) mobText.textContent = `雲端同步 ${nowStr}`;
    if (modalBox) modalBox.className = 'p-3.5 rounded-xl border bg-matte-sub border-matte-border flex items-center justify-between gap-3';
    if (modalTitle) modalTitle.innerHTML = '● Supabase 資料表已連線成功！所有資料皆即時儲存於雲端';
  } else {
    if (banner) banner.classList.remove('hidden');
    [authDot, sideDot, mobDot].forEach(el => {
      if (el) el.className = 'w-2 h-2 rounded-full bg-stone-400 live-dot shrink-0';
    });
    if (authStatus) authStatus.textContent = '待執行 SQL 初始化 (目前支援即時快取體驗)';
    if (sideText) sideText.textContent = `待初始化資料表 (快取 ${nowStr})`;
    if (mobText) mobText.textContent = `待建表同步 ${nowStr}`;
    if (modalBox) modalBox.className = 'p-3.5 rounded-xl border bg-matte-sub border-matte-border flex items-center justify-between gap-3';
    if (modalTitle) modalTitle.innerHTML = '○ 尚未在 Supabase 建立資料表（請複製下方 SQL 執行）';
  }
}

async function manualRefreshData() {
  const ok = await fetchAllFromSupabase(true);
  if (ok) {
    showToast('已從 Supabase 同步最新即時資料！', 'success');
  } else {
    showToast('目前為本機即時模式，請先至資料庫設定執行 SQL 語法', 'info');
  }
}

// ============================================================================
// 登入與身分驗證 (無公開註冊，註冊僅限管理者於設定頁操作)
// ============================================================================

function fillDemoAccount(username, password) {
  document.getElementById('login-username').value = username;
  document.getElementById('login-password').value = password;
  showToast(`已帶入帳號 ${username}，點擊「登入排球隊系統」即可進入`, 'info');
}

async function handleLogin(e) {
  e.preventDefault();
  const username = document.getElementById('login-username').value.trim();
  const password = document.getElementById('login-password').value.trim();

  if (!username || !password) {
    showToast('請輸入帳號與密碼！', 'error');
    return;
  }

  // 確保本機名冊已就緒
  if (!state.users || state.users.length === 0) {
    loadLocalCache();
  }

  const matchUser = (u) => {
    const uName = (u.name || '').toLowerCase();
    const uUser = (u.username || '').toLowerCase();
    const target = username.toLowerCase();

    const isMatchIdentity = (
      uUser === target ||
      uName === target ||
      (target === 'admin' && u.role === 'admin')
    );

    const isMatchPassword = (
      u.password === password ||
      (u.role === 'admin' && (password === 'ntubad001' || password === 'admin'))
    );

    return isMatchIdentity && isMatchPassword;
  };

  // 1. 優先從記憶體/本機快取比對，秒速登入（不卡頓）
  let found = state.users.find(matchUser);

  // 2. 若本機未找到，嘗試至雲端 Supabase 同步更新名單（限時 2 秒避免無回應）
  if (!found && supabaseClient) {
    try {
      await Promise.race([
        fetchAllFromSupabase(false),
        new Promise(resolve => setTimeout(resolve, 2000))
      ]);
      found = state.users.find(matchUser);
    } catch (err) {
      console.warn('Login cloud sync warning:', err);
    }
  }

  if (!found) {
    showToast('帳號或密碼錯誤，請重新確認！', 'error');
    return;
  }

  loginSuccess(found);

  // 登入成功後於背景非同步檢查雲端更新
  if (supabaseClient) {
    fetchAllFromSupabase(false).catch(() => {});
  }
}

function loginSuccess(user) {
  state.currentUser = user;
  sessionStorage.setItem(SESSION_USER_KEY, JSON.stringify(user));

  document.getElementById('auth-screen').classList.add('hidden');
  document.getElementById('app-screen').classList.remove('hidden');

  state.activeTab = 'dashboard';
  ['filter-fitness-member', 'filter-fee-member', 'filter-leave-member'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = 'all';
  });

  renderNavigation();
  renderAll();
  showToast(`歡迎，${user.name} (${user.role === 'admin' ? '管理者' : '球員'})`, 'success');
}

function handleLogout() {
  state.currentUser = null;
  sessionStorage.removeItem(SESSION_USER_KEY);
  document.getElementById('app-screen').classList.add('hidden');
  document.getElementById('auth-screen').classList.remove('hidden');
  lucide.createIcons();
}

// ============================================================================
// 管理者「粗略項目(彙整) ↔ 細項明細(逐筆)」模式切換與下鑽
// ============================================================================

function setAdminViewMode(mode) {
  state.adminViewMode = mode;
  if (mode === 'summary') {
    state.fitnessSubTab = 'matrix';
    state.feesSubTab = 'overview';
    state.leavesSubTab = 'calendar';
    state.financesSubTab = 'overview';
  } else {
    if (state.fitnessSubTab !== 'makeup') state.fitnessSubTab = 'matrix';
    if (state.feesSubTab === 'overview') state.feesSubTab = 'all';
    state.leavesSubTab = 'leave';
    state.financesSubTab = 'list';
  }
  updateAdminViewModeButtons();
  renderAll();
}

function renderSubTabBannerHtml(containerId, sectionKey, sectionTitle, subTabs, activeSubId) {
  const bar = document.getElementById(containerId);
  if (!bar) return;
  const colClass = subTabs.length === 4
    ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-4'
    : subTabs.length === 2
      ? 'grid-cols-1 sm:grid-cols-2'
      : 'grid-cols-1 md:grid-cols-3';

  bar.innerHTML = `
    <div class="grid ${colClass} gap-2 sm:gap-2.5">
      ${subTabs.map(tab => {
        const isActive = activeSubId === tab.id;
        const hasBadge = Boolean(tab.badge && !tab.badge.startsWith('區塊'));
        return `
          <button type="button" onclick="switchSectionSubTab('${escapeJsStr(sectionKey)}', '${escapeJsStr(tab.id)}')"
            class="px-3.5 py-2.5 rounded-xl border text-left transition flex items-center justify-between gap-3 ${
              isActive
                ? 'bg-[#1c1b18] text-stone-100 border-[#1c1b18] shadow-sm ring-2 ring-stone-500'
                : 'bg-matte-sub hover:bg-stone-300/80 text-matte-ink border-matte-border'
            }">
            <div class="min-w-0 flex-1 space-y-0.5">
              <div class="font-extrabold text-xs sm:text-sm leading-snug flex items-center gap-1.5 truncate">
                ${hasBadge ? `
                  <span class="px-1.5 py-0.2 rounded text-[10px] font-extrabold shrink-0 ${
                    isActive ? 'bg-stone-700 text-stone-100' : 'bg-stone-300 text-matte-ink'
                  }">${escapeHtml(tab.badge)}</span>
                ` : ''}
                <span class="truncate">${escapeHtml(tab.title)}</span>
              </div>
              <p class="text-[11px] truncate leading-tight ${isActive ? 'text-stone-300' : 'text-matte-muted'}">${escapeHtml(tab.desc || tab.subtitle || '')}</p>
            </div>
            <i data-lucide="${escapeHtml(tab.icon || 'folder')}" class="w-4 h-4 shrink-0 ${isActive ? 'text-stone-200' : 'text-matte-muted'}"></i>
          </button>
        `;
      }).join('')}
    </div>
  `;
}

function switchSectionSubTab(sectionKey, subTabId) {
  const isAdmin = state.currentUser && state.currentUser.role === 'admin';
  if (sectionKey === 'dashboard') {
    state.dashboardSubTab = subTabId;
    renderDashboardSection();
  } else if (sectionKey === 'schedule') {
    state.scheduleSubTab = subTabId;
    renderAdminScheduleSection();
  } else if (sectionKey === 'fitness') {
    state.fitnessSubTab = ['matrix', 'makeup', 'makeupStats'].includes(subTabId) ? subTabId : 'matrix';
    renderFitnessSection();
  } else if (sectionKey === 'fees') {
    state.feesSubTab = subTabId;
    const typeSelect = document.getElementById('filter-fee-type');
    if (subTabId === 'team' && typeSelect) typeSelect.value = '隊費';
    else if (subTabId === 'proxy' && typeSelect) typeSelect.value = '代繳費用';
    else if (subTabId === 'all' && typeSelect) typeSelect.value = 'all';
    if (isAdmin) {
      state.adminViewMode = subTabId === 'overview' ? 'summary' : 'detail';
      updateAdminViewModeButtons();
    }
    renderFeesSection();
  } else if (sectionKey === 'leaves') {
    if (subTabId === 'equipment') {
      switchTab('equipment');
      return;
    }
    if (subTabId === 'makeupStats') {
      switchTab('fitness');
      switchSectionSubTab('fitness', 'makeupStats');
      return;
    }
    // 舊版子分頁代號相容轉換
    const legacyMap = { attendance: 'leave', overview: 'leave', list: 'leave' };
    const targetSub = legacyMap[subTabId] || subTabId;
    if (!isAdmin && targetSub === 'leave') {
      state.leavesSubTab = 'calendar';
    } else {
      state.leavesSubTab = targetSub;
    }
    renderLeavesSection();
  } else if (sectionKey === 'finances') {
    state.financesSubTab = subTabId;
    if (isAdmin) {
      state.adminViewMode = subTabId === 'overview' ? 'summary' : 'detail';
      updateAdminViewModeButtons();
    }
    renderFinancesSection();
  } else if (sectionKey === 'settings') {
    state.settingsSubTab = subTabId;
    renderSettingsSection();
  }
  lucide.createIcons();
}

function updateAdminViewModeButtons() {
  const switcher = document.getElementById('admin-view-mode-switcher');
  if (switcher) switcher.classList.add('hidden');
}

function drillDownFitnessByTask(taskName) {
  const dateMatch = (taskName || '').match(/\d{4}-\d{2}-\d{2}/);
  if (dateMatch) {
    state.selectedFitnessDate = dateMatch[0];
  }
  state.fitnessSubTab = 'matrix';
  setAdminViewMode('detail');
  showToast(`已切換至個人細項明細`, 'info');
}

function drillDownFitnessByMember(userId) {
  const searchEl = document.getElementById('filter-fitness-search');
  const memberEl = document.getElementById('filter-fitness-member');
  if (searchEl) searchEl.value = '';
  if (memberEl) memberEl.value = 'all';
  if (userId.startsWith('name:')) {
    state.selectedFitnessPlayer = userId.slice(5);
  } else {
    const u = state.users.find(x => x.id === userId);
    if (u) state.selectedFitnessPlayer = u.name;
  }
  state.selectedFitnessDate = '';
  state.fitnessSubTab = 'matrix';
  setAdminViewMode('detail');
}

function openPlayerFitnessDetail(playerName, dateStr = '') {
  if (playerName) {
    state.selectedFitnessPlayer = playerName;
  }
  if (dateStr && !isDateInAcademicPeriod(dateStr, state.selectedAcademicYear, state.selectedTermPeriod)) {
    const info = getAcademicTermInfo(dateStr);
    state.selectedAcademicYear = String(info.academicYear);
    state.selectedTermPeriod = info.period;
    syncAcademicFilterDropdowns();
  }
  const playerRecords = state.fitness
    .filter(f =>
      f.user_name === state.selectedFitnessPlayer &&
      isDateInAcademicPeriod(f.target_date, state.selectedAcademicYear, state.selectedTermPeriod)
    )
    .sort((a, b) => (b.target_date || '').localeCompare(a.target_date || ''));
  if (dateStr && playerRecords.some(f => f.target_date === dateStr)) {
    state.selectedFitnessDate = dateStr;
  } else if (!playerRecords.some(f => f.target_date === state.selectedFitnessDate)) {
    state.selectedFitnessDate = playerRecords.length > 0 ? playerRecords[0].target_date : '';
  }
  state.fitnessSubTab = 'matrix';
  if (state.currentUser && state.currentUser.role === 'admin') {
    setAdminViewMode('detail');
  } else {
    renderFitnessSection();
    lucide.createIcons();
  }
}

function onSelectFitnessMemberDropdown(val) {
  if (val === 'all') {
    // keep current matrix player
  } else if (val.startsWith('name:')) {
    state.selectedFitnessPlayer = val.slice(5);
    state.selectedFitnessDate = '';
  } else {
    const u = state.users.find(x => x.id === val);
    if (u) {
      state.selectedFitnessPlayer = u.name;
      state.selectedFitnessDate = '';
    }
  }
  renderFitnessSection();
}

function selectFitnessMatrixPlayer(playerName) {
  state.selectedFitnessPlayer = playerName;
  const playerRecords = state.fitness
    .filter(f =>
      f.user_name === playerName &&
      isDateInAcademicPeriod(f.target_date, state.selectedAcademicYear, state.selectedTermPeriod)
    )
    .sort((a, b) => (b.target_date || '').localeCompare(a.target_date || ''));
  // 選擇成員後預設為最新的紀錄
  state.selectedFitnessDate = playerRecords.length > 0 ? playerRecords[0].target_date : '';
  renderFitnessSection();
}

